            for i, lv in enumerate(livres):
                c.execute("INSERT INTO qnap_snapshot (coletado_em, montado, total_gb, livre_gb) VALUES (datetime('now', ?), 1, ?, ?)", (f"-{len(livres) - 1 - i} days", total, lv))
